/bin/zsh -lc "node <<'NODE'
const assert = require('node:assert/strict');
const cases = [
  ['staged.js', 'double', 2, 4],
  ['unstaged.js', 'half', 2, 1],
  ['untracked.js', 'position', 0, 1],
];
let failures = 0;
for (const [file, name, input, expected] of cases) {
  const actual = require("'`./${file}`)[name](input);
  try {
    assert.equal(actual, expected);
    console.log(`PASS ${file}: ${name}(${input})`);
  } catch {
    failures++;
    console.log(`FAIL ${file}: ${name}(${input}) = ${actual}; expected ${expected}`);
  }
}
process.exitCode = failures ? 1 : 0;
NODE'

